contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a scenario: deposit some ether, then attempt a withdraw(amount).
    // Parameters:
    // - depositAmount: amount to deposit into c from this contract
    // - withdrawAmount: amount to attempt to withdraw
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // initial observed balance for this contract in C
        uint256 beforeUserBal = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        // deposit into c (send Ether)
        c.deposit{value: depositAmount}();

        // read balances after deposit
        uint256 afterDepositUserBal = c.balances(address(this));
        uint256 afterDepositContractBal = address(c).balance;

        // withdraw attempt: record whether it reverted
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // read balances after withdraw attempt
        uint256 finalUserBal = c.balances(address(this));
        uint256 finalContractBal = address(c).balance;

        // If withdraw did not revert then:
        // 1) caller's recorded balance decreased by exactly withdrawAmount
        // 2) contract's Ether balance decreased by exactly withdrawAmount
        // Otherwise (it reverted), both balances remain equal to after-deposit values
        assert(
            (!withdrewReverted && afterDepositUserBal >= withdrawAmount &&
                finalUserBal + withdrawAmount == afterDepositUserBal &&
                finalContractBal + withdrawAmount == afterDepositContractBal)
            || (withdrewReverted && finalUserBal == afterDepositUserBal && finalContractBal == afterDepositContractBal)
        );
    }

    // allow receiving Ether so this contract can fund deposits/receive refunds
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read C.balances (it's not public), so we observe effects via Ether flows:
    // depositAmount: amount to deposit into c from this contract
    // withdrawAmount: amount to attempt to withdraw
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // initial contract balance
        uint256 beforeContractBal = address(c).balance;
        // initial this contract balance (observable)
        uint256 beforeThisBal = address(this).balance;

        // deposit into c
        c.deposit{value: depositAmount}();

        // balances after deposit
        uint256 afterDepositContractBal = address(c).balance;
        uint256 afterDepositThisBal = address(this).balance;

        // Attempt withdraw and record whether it reverted. If successful, this contract should receive Ether.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // balances after withdraw attempt
        uint256 finalContractBal = address(c).balance;
        uint256 finalThisBal = address(this).balance;

        // If withdraw succeeded then contract balance decreased by withdrawAmount and this contract balance increased by withdrawAmount.
        // If it reverted then both balances remain equal to their post-deposit values.
        assert(
            (!withdrewReverted &&
                afterDepositContractBal >= withdrawAmount &&
                finalContractBal + withdrawAmount == afterDepositContractBal &&
                finalThisBal == afterDepositThisBal + withdrawAmount)
            || (withdrewReverted && finalContractBal == afterDepositContractBal && finalThisBal == afterDepositThisBal)
        );
    }

    // allow receiving Ether so withdraw/refund can send Ether here
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount to deposit into c from this contract, then call refund()
    function run(uint256 depositAmount) public payable {
        // ensure the test contract has enough Ether to deposit
        require(address(this).balance >= depositAmount);

        // record contract balances before any interaction
        uint256 c_before = address(c).balance;
        uint256 me_before = address(this).balance;

        // perform deposit (may revert if overflow in C.deposit); we let that revert be part of behavior
        c.deposit{value: depositAmount}();

        // record balances after deposit
        uint256 c_after_deposit = address(c).balance;
        uint256 me_after_deposit = address(this).balance;

        // call refund and record whether it reverted
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // balances after refund attempt
        uint256 c_final = address(c).balance;
        uint256 me_final = address(this).balance;

        // General rule: If refund did NOT revert, then this call transferred exactly the amount that this test contract had just deposited
        // (i.e., me_final == me_after_deposit + depositAmount) and C's balance decreased by that same amount.
        // If refund reverted, balances remain as after_deposit.
        assert(
            (!refundReverted && me_final == me_after_deposit + depositAmount && c_final + depositAmount == c_after_deposit)
            || (refundReverted && me_final == me_after_deposit && c_final == c_after_deposit)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to deposit from this test contract into c (so address(c).balance > 0),
    // then attempt migrateTo by specifying who calls it: either this contract should act as creator
    // or not. Because the checker deploys a fresh c and passes it to this test's constructor, the
    // deployer of c is the test harness, not this contract; however the only externally visible
    // way to trigger migrateTo is via calling c.migrateTo. Here we assert that when migrateTo
    // succeeds (i.e., called by the creator), address(c).balance becomes zero; and when it is
    // called by a non-creator it must revert and leave address(c).balance unchanged. We also
    // assert that a non-creator's per-address recorded balance (queried via the public getter)
    // is not decreased by migrateTo: migrateTo only moves the contract's global balance.

    function run(uint256 depositAmount, address to) public payable {
        // ensure the test contract has enough Ether to deposit
        require(address(this).balance >= depositAmount);

        // record c's global balance before any action
        uint256 c_before = address(c).balance;

        // record this contract's recorded balance in c (via the public balances getter)
        // Note: balances is defined in C as mapping(address=>uint256) balances; it is not public in
        // the provided contract, so we cannot call c.balances(...). Instead we observe that C has
        // no public getter for per-address balances. To adhere to the constraints, we must only
        // observe address(c).balance and effects of migrateTo. Therefore we adjust the rule to
        // assert only on global balance and revert behavior.

        // deposit into c to ensure there is some Ether to migrate; deposit may revert if C.deposit
        // assert inside deposit fails due to overflow — in that case the test will revert and is
        // not required to reach the final assert. To avoid hitting the assert inside C.deposit, we
        // constrain depositAmount to be small enough: require depositAmount > 0.
        require(depositAmount > 0);

        // perform deposit from this contract into c
        c.deposit{value: depositAmount}();

        // record c balance after deposit
        uint256 c_after_deposit = address(c).balance;

        // Try calling migrateTo as this contract (which is NOT the creator of C since creator is
        // the account that deployed C — the test harness). Capture whether it reverts.
        bool migrateReverted;
        try c.migrateTo(to) {
            migrateReverted = false;
        } catch {
            migrateReverted = true;
        }

        uint256 c_final = address(c).balance;

        // General rule:
        // - If migrateTo did NOT revert, then it must have moved the entire contract balance out,
        //   so address(c).balance == 0.
        // - If migrateTo DID revert (caller was not creator), c's balance must be unchanged from
        //   just after deposit (i.e., migrate attempted no global transfer).
        assert((!migrateReverted && c_final == 0) || (migrateReverted && c_final == c_after_deposit));
    }

    receive() external payable { }
}

