        // Ensure this test contract can receive Ether refunds from C if needed
        // No precondition on c's state; we just try withdraw and observe effects.

        uint256 beforeContractBal = address(c).balance;
        uint256 beforeThisBal = address(this).balance;

        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBal = address(c).balance;
        uint256 afterThisBal = address(this).balance;

        // General rule:
        // If withdraw did not revert, then the contract's balance decreased by at least amount
        // and this contract's balance increased by at least amount (i.e., the caller received >= amount).
        // If it reverted, balances stayed the same.
        assert(reverted ? (afterContractBal == beforeContractBal && afterThisBal == beforeThisBal)
                        : (beforeContractBal >= afterContractBal && beforeThisBal + amount <= afterThisBal && beforeContractBal - afterContractBal >= amount));
    }

