contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test drives deposit and refund; takes deposit amount as parameter and a flag whether to call refund.
    function run(uint256 depositAmount, bool doRefund) public payable {
        require(address(this).balance >= depositAmount);

        // Ensure fresh starting point: deposit some funds into c from this contract (msg.sender inside c is this contract)
        c.deposit{value: depositAmount}();

        // Read recorded balance for this contract (public mapping getter)
        uint256 recordedBefore = c.balances(address(this));
        // Read contract's Ether balance before refund
        uint256 balanceBefore = address(c).balance;

        bool reverted = false;
        if (doRefund) {
            try c.refund() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 recordedAfter = c.balances(address(this));
        uint256 balanceAfter = address(c).balance;

        // General rule:
        // If refund was attempted and did not revert, then recorded balance for caller is zero
        // and the contract's balance decreased by at least the recordedBefore amount.
        // If refund reverted or was not attempted, nothing is asserted about balances changing.
        assert(!doRefund || reverted || (recordedAfter == 0 && balanceBefore - balanceAfter >= recordedBefore));
    }

    receive() external payable {}
}

