        c.deposit{value: depositAmount}();

        // Observe contract balance before refund
        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;

        bool reverted = false;
        if (doRefund) {
            try c.refund() {
                reverted = false;
            } catch {
                reverted = true;
            }
