    // We take depositAmt to send with deposit, and withdrawAmt to withdraw afterward.
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // perform deposit into c sending depositAmt wei
        c.deposit{value: depositAmt}();

        // read balance recorded for this contract in c (auto-generated getter for balances)
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeContractBalance = address(c).balance;

        // attempt withdraw and record whether it reverted
        bool reverted;
        try c.withdraw(withdrawAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRecorded = c.balances(address(this));
        uint256 afterContractBalance = address(c).balance;

        // General rule:
        // If withdraw succeeded then recorded balance decreases by exactly withdrawAmt
        // and contract balance decreases by at least withdrawAmt.
        // If withdraw reverted then recorded balance and contract balance are unchanged.
        assert(
            reverted
                ? (afterRecorded == beforeRecorded && afterContractBalance == beforeContractBalance)
                : (beforeRecorded >= withdrawAmt && afterRecorded + withdrawAmt == beforeRecorded && beforeContractBalance >= afterContractBalance && beforeContractBalance - afterContractBalance >= withdrawAmt)
