contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot directly read the internal mapping balances (it's not public), so we infer the caller's recorded balance by using withdraw behavior:
    // - If withdraw(amount) succeeds, then a subsequent withdraw of amountRemaining should succeed only if amountRemaining <= previous_balance - amount.
    // - We use address(c).balance as observable contract balance.

    function run(uint256 depositAmt, uint256 withdrawAmt, uint256 probeAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // deposit into c from this contract
        c.deposit{value: depositAmt}();

        uint256 beforeContractBalance = address(c).balance;

        // attempt the primary withdraw and record whether it reverted
        bool primaryReverted;
        try c.withdraw(withdrawAmt) {
            primaryReverted = false;
        } catch {
            primaryReverted = true;
        }

        uint256 afterContractBalance = address(c).balance;

        // Now attempt a probe withdraw to learn about the caller's remaining recorded balance.
        // If primary withdraw succeeded, then the remaining recorded balance should be old_balance - withdrawAmt.
        // We can't read old_balance directly, but we can observe whether a probe withdraw of probeAmt succeeds.
        bool probeReverted;
        try c.withdraw(probeAmt) {
            probeReverted = false;
        } catch {
            probeReverted = true;
        }

        // The general rule we assert:
        // - If primary withdraw reverted: contract balance unchanged and probe behavior is as if no funds were removed (i.e., probe success implies sufficient balance independent of primary call).
        // - If primary withdraw succeeded: contract balance decreased by at least withdrawAmt, and probe success implies that either probeAmt <= previous_balance - withdrawAmt.
        // We encode this as:
        //   primaryReverted => afterContractBalance == beforeContractBalance
        //   !primaryReverted => beforeContractBalance >= afterContractBalance && (beforeContractBalance - afterContractBalance) >= withdrawAmt
        // Additionally, ensure the assertion is nontrivial by relating probe outcome: if primary succeeded and probe succeeded then it's possible that probeAmt <= previous_balance - withdrawAmt, which implies nothing directly observable numerically without access to previous_balance; however the observable part we can assert is that the contract's balance change is consistent with at least withdrawAmt when primary succeeded.

        assert(
            primaryReverted
                ? (afterContractBalance == beforeContractBalance)
                : (beforeContractBalance >= afterContractBalance && (beforeContractBalance - afterContractBalance) >= withdrawAmt)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot read internal balances mapping, so we infer effects via address(c).balance and double-calling refund.
    // Parameters:
    //  - depositAmt: amount this test will deposit into c before calling refund
    // No msg.value is used to pay for deposit; instead we require this contract has enough balance and use c.deposit{value: depositAmt}()
    function run(uint256 depositAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // Make an initial deposit so c records a balance for this contract (msg.sender == InvMutTest)
        c.deposit{value: depositAmt}();

        uint256 beforeBalance = address(c).balance;

        // First attempt refund and record if it reverted
        bool firstReverted;
        try c.refund() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 midBalance = address(c).balance;

        // Second refund attempt to check that after a successful refund no more funds are sent to this caller
