    // We take an input depositAmount and perform a deposit; then assert that
    // 1) the recorded balance for this caller (as observable by attempting a withdraw of the full recorded balance and seeing it not necessarily revert) is never greater than address(c).balance,
    // 2) and that calling deposit with a nonzero amount never decreases the observed recorded balance (i.e., record before and after via a withdraw-try of a very large amount to probe available balance).
    // To observe the per-caller recorded balance we use withdraw in a try/catch: if withdraw(x) succeeds then caller had at least x recorded; if it reverts then caller had less than x.

    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Probe recorded balance before deposit by binary search style probing is expensive; instead we probe two facts with a single value:
        // Try to withdraw a very large amount to see whether recorded balance was already large.
        bool beforeWithdrawSucceeded;
        try c.withdraw(type(uint256).max) {
            beforeWithdrawSucceeded = true;
        } catch {
            beforeWithdrawSucceeded = false;
        }

        // Perform the deposit (this may revert if deposit overflows internal accounting, in which case this execution path won't reach the final assert — that's fine as the checker must find a path that reaches the assert)
        c.deposit{value: depositAmount}();

        // After deposit, probe withdraw of the same large amount again
        bool afterWithdrawSucceeded;
        try c.withdraw(type(uint256).max) {
            afterWithdrawSucceeded = true;
        } catch {
            afterWithdrawSucceeded = false;
        }

        // Observe contract total balance
        uint256 total = address(c).balance;

        // General invariant to assert:
        // - The caller's recorded balance (as observed by the success of withdrawing a huge amount) cannot be greater than the contract's total balance: if withdraw(type(uint).max) succeeds then address(c).balance must be > 0 (in fact >= some positive amount), but to avoid subtraction/precise amounts we assert that success implies contract has nonzero balance.
        // - Depositing cannot make the very-large-withdraw probe go from success to failure (i.e., deposit does not decrease the observable recorded balance for this caller).
        assert(
            // If afterWithdrawSucceeded then contract must have nonzero balance
            ((afterWithdrawSucceeded && total > 0) || !afterWithdrawSucceeded)
            // And deposit did not flip success -> failure
            && (!(beforeWithdrawSucceeded == true && afterWithdrawSucceeded == false))
        );
    }

    receive() external payable { }
}

