        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // try to deposit depositAmount into c as this contract
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // record balances after deposit attempt
        uint256 afterC_afterDeposit = address(c).balance;
        uint256 afterThis_afterDeposit = address(this).balance;

