        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // observe balances after refund attempt
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General invariant to assert:
        // If refund succeeded then the net gain to this contract equals the decrease in c's balance,
        // and that decrease is at most the amount previously deposited by this contract (i.e., depositAmount if deposit succeeded, else 0).
        // If refund reverted then balances must be unchanged by the refund call.

        // compute observed deltas
        // avoid underflow by comparing and using >=
        bool deltaMatches;
        if (!refundReverted) {
            // refund succeeded: this contract's balance must have increased by exactly the amount c's balance decreased
            uint256 gainThis = afterThis >= afterThis_afterDeposit ? afterThis - afterThis_afterDeposit : 0;
            uint256 lossC = afterC_afterDeposit >= afterC ? afterC_afterDeposit - afterC : 0;
            // Also lossC cannot exceed what we had deposited: if deposit reverted then depositAmount didn't enter c
            uint256 maxPossible = depositReverted ? 0 : depositAmount;
            deltaMatches = (gainThis == lossC) && (lossC <= maxPossible);
        } else {
