    // than the original amount must revert (because recorded balance decreased by at least amount).
    function run(uint256 depositAmount, uint256 withdrawAmount, uint256 extraAttempt) public payable {
        // ensure we can forward depositAmount if we try to deposit
        require(address(this).balance >= depositAmount);

        // Try to deposit depositAmount into c from this contract
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
