        bool firstWithdrawReverted;
        try c.withdraw(withdrawAmount) {
            firstWithdrawReverted = false;
        } catch {
            firstWithdrawReverted = true;
        }

        // Now attempt a second withdraw of extraAttempt (> withdrawAmount) to check that recorded balance decreased by at least withdrawAmount when first withdraw succeeded.
        bool secondWithdrawReverted;
        // We only attempt this second withdraw if the first withdraw succeeded; otherwise behavior irrelevant for this rule.
        if (!firstWithdrawReverted) {
            // calling second withdraw; it should revert if extraAttempt is strictly greater than remaining recorded balance.
            // We don't know remaining recorded balance but we assert that any extraAttempt > withdrawAmount must revert.
            try c.withdraw(extraAttempt) {
                secondWithdrawReverted = false;
            } catch {
                secondWithdrawReverted = true;
            }
        } else {
            // If first withdraw reverted, we didn't change state; secondWithdrawReverted is unused but set deterministically
            secondWithdrawReverted = true;
        }

        // General rule asserted:
        // If the first withdraw succeeded then any second withdraw with extraAttempt > withdrawAmount must revert.
        // If the first withdraw reverted then we assert nothing about secondWithdraw (we require nothing). To keep assert general, encode both cases.
        assert( firstWithdrawReverted || (extraAttempt <= withdrawAmount || secondWithdrawReverted) );
    }

    // allow receiving Ether (so deposits and refunds can send Ether back)
    receive() external payable {}
}

