contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will not call deposit to avoid hitting deposit's assert. Instead we only test refund behavior
    // for the fresh contract state where balances may be zero. To observe a nonzero recorded balance
    // we first fund the contract by having the creator (this contract, as it deployed c) call migrateTo will not help.
    // So instead we rely on any observable behavior: the rule asserts that if refund succeeds then
    // the test contract's balance increases exactly by the prior recorded balance as observed by
    // the fact that after refund any withdraw of an amount greater than that prior balance must revert.

    // We cannot read balances mapping directly; instead we perform a sequence:
    // 1) Attempt refund(), recording whether it reverted and capturing address(this).balance delta.
    // 2) After a successful refund, assert that any subsequent withdraw(priorBalance + 1) by this contract reverts.

    // To make this work without knowing priorBalance numerically, we use the following logical characterization:
    // Let delta be the increase in address(this).balance caused by refund (0 if refund reverted).
    // If refund succeeded then calling withdraw(delta + 1) must revert (because refund should have zeroed the recorded balance).
    // If refund reverted then no balance increase occurred (delta == 0).

    function run() public payable {
        // record balance before
        uint256 before = address(this).balance;

        // Attempt refund()
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        uint256 after = address(this).balance;
        // delta is the observed increase (may be 0)
        uint256 delta = (after >= before) ? (after - before) : 0;

        // Now attempt withdraw(delta + 1) and expect it to revert if refund succeeded.
        bool withdrawReverted;
        // ensure we don't pass arithmetic with overflow: delta + 1 is safe as delta <= address(c).balance + address(this).balance
        uint256 tryAmount = delta + 1;
        try c.withdraw(tryAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Assert the general rule:
        // - If refund reverted then delta == 0.
        // - If refund succeeded then withdraw(delta+1) must revert (i.e., recorded balance was cleared to 0 and equal to delta).
        assert( (refundReverted && delta == 0) || (!refundReverted && withdrawReverted) );
    }

    receive() external payable {}
}

