        }

        // Compute observed increase in contract balance due to our deposit attempts
        uint256 midC = address(c).balance;
        uint256 observedRecordedBalance;
        if (depositReverted) {
            // If deposit reverted, we cannot assume any recorded balance was added by that deposit
            observedRecordedBalance = 0;
        } else {
            // If deposit succeeded, the contract's balance should have increased by at least depositAmount
            // The recorded prior balance for this caller must be <= the total increase we caused in this txn,
            // but since only this caller deposited, we take the observed increase as the caller's recorded balance contribution.
            observedRecordedBalance = midC - beforeC;
        }

        // Now call refund and capture whether it reverted
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // Observables after refund attempt
        uint256 afterC = address(c).balance;

        // General rule: If refund succeeded then the caller's recorded balance becomes zero and the contract's balance
        // is reduced by at least the caller's prior recorded balance (which we observed as observedRecordedBalance).
        // We cannot read the mapping directly, so we assert the effect on address(c).balance.
        assert(refundReverted || afterC + observedRecordedBalance <= midC);
    }

    receive() external payable {}
}

