            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCBalance = address(c).balance;

        // The general rule we assert: if refund succeeded, the contract's balance decreased by exactly the amount that was sent to the caller (which equals the caller's recorded balance just before refund), and the caller's recorded balance is now observable as zero by attempting a withdraw of any positive amount (which must revert).
        // We express the observable part: after a successful refund, any withdraw(1) by this contract must revert because its recorded balance must be zero; if refund reverted, then withdraw(0) must succeed (withdraw(0) is allowed and should not revert) — we use try/catch to test withdraw(1) behavior.

        if (!reverted) {
            // refund succeeded: contract balance must have decreased (or stayed same if zero refund) by some amount equal to the old recorded balance.
            // We assert that afterCBalance <= beforeCBalance and that withdrawing 1 now reverts (since caller's balance was cleared to zero).
            bool withdrawReverted;
            try c.withdraw(1) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }

            assert(afterCBalance <= beforeCBalance && withdrawReverted);
        } else {
            // refund reverted: then withdraw(0) must not revert (withdrawing zero should be allowed and not change balances)
            bool withdrawZeroReverted;
            try c.withdraw(0) {
                withdrawZeroReverted = false;
            } catch {
                withdrawZeroReverted = true;
            }

            assert(withdrawZeroReverted == false);
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    function run(uint256 depositAmount) public payable {
        // ensure this contract has enough Ether to send depositAmount to c
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // make a deposit into c as msg.sender = this contract
        c.deposit{value: depositAmount}();

        // record contract balance before refund
        uint256 beforeCBalance = address(c).balance;

        // attempt refund and record whether it reverted
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // record contract balance after refund attempt
        uint256 afterCBalance = address(c).balance;

        // attempt withdraw(1) and withdraw(0) to observe post-refund behavior
        bool withdraw1Reverted;
        try c.withdraw(1) {
            withdraw1Reverted = false;
        } catch {
            withdraw1Reverted = true;
        }

        bool withdraw0Reverted;
        try c.withdraw(0) {
            withdraw0Reverted = false;
        } catch {
            withdraw0Reverted = true;
        }

        // Single general assertion combining both branches:
        // - If refund succeeded (refundReverted == false) then afterCBalance <= beforeCBalance and withdraw(1) must revert.
        // - If refund reverted (refundReverted == true) then withdraw(0) must succeed (not revert).
        assert((!refundReverted && afterCBalance <= beforeCBalance && withdraw1Reverted) || (refundReverted && !withdraw0Reverted));
    }

    receive() external payable { }
}
